"""Lua diagnostics for the category-1 AUX event dispatch.

The host runs setup in a Map Script child, calls LAB_Aux90Dispatch on the root
with the event name, then runs verify in that child. This checks the shared
LuaEventsByContext[1] factory path end to end.
"""
from civ6_host.runtime.provenance import historical_source_file as _historical_source_file, historical_module_file as _historical_module_file, worker_path as _worker_path, pin_key as _pin_key, installed_source_pins as _installed_source_pins
from civ6_host.runtime.resource_resolution import resolve_path as _resolve_resource_path
AUX_EVENT_CASES = {'dispatch_setup': "\n        local event = LuaEvents.Civ6RL_AuxEventInjection\n        assert(type(event) == 'table')\n        assert(type(event.Add) == 'function' and type(event.Call) == 'function')\n        assert(type(event.Remove) == 'function' and type(event.RemoveAll) == 'function')\n        assert(type(event.Count) == 'function')\n        event.RemoveAll()\n        Civ6RL_AuxEventSeen = 0\n        Civ6RL_AuxEventListener = function()\n            Civ6RL_AuxEventSeen = Civ6RL_AuxEventSeen + 1\n        end\n        assert(event.Add(Civ6RL_AuxEventListener)==Civ6RL_AuxEventListener)\n        assert(event.Count() == 1)\n    ", 'dispatch_verify_and_cleanup': "\n        local event = LuaEvents.Civ6RL_AuxEventInjection\n        assert(Civ6RL_AuxEventSeen == 1, 'AUX dispatch did not invoke listener')\n        event.Remove(Civ6RL_AuxEventListener)\n        assert(event.Count() == 0)\n        Civ6RL_AuxEventListener = nil\n        Civ6RL_AuxEventSeen = nil\n    ", 'remove_all': '\n        local event = LuaEvents.Civ6RL_AuxEventRemoveAll\n        event.RemoveAll()\n        event.Add(function() end)\n        assert(event.Count() == 1)\n        event.RemoveAll()\n        assert(event.Count() == 0)\n    ', 'additional_listener_refusal': "\n        local event = LuaEvents.Civ6RL_AuxEventSecondListener\n        event.RemoveAll()\n        event.Add(function() end)\n        local ok, message = pcall(event.Add, function() end)\n        assert(not ok and string.find(message, 'currently supports one listener', 1, true))\n        event.RemoveAll()\n    ", 'duplicate_listener_refusal': "\n        local event = LuaEvents.Civ6RL_AuxEventDuplicate\n        event.RemoveAll()\n        local listener = function() end\n        event.Add(listener)\n        local ok, message = pcall(event.Add, listener)\n        assert(not ok and string.find(message, 'duplicate LuaEvents listener', 1, true))\n        event.RemoveAll()\n    ", 'mutation_during_call_refusal': "\n        local event = LuaEvents.Civ6RL_AuxEventMutation\n        event.RemoveAll()\n        local listener = function()\n            local ok, message = pcall(event.RemoveAll)\n            assert(not ok and string.find(message, 'mutation during Call', 1, true))\n        end\n        event.Add(listener)\n        event.Call()\n        assert(event.Count() == 1)\n        event.RemoveAll()\n    "}
